class BIT2D:
    def __init__(self, n={{n}}, m={{m}}):
        self.n, self.m = n, m
        self.t = [[0]*(m+1) for _ in range(n+1)]
    def update(self, x, y, v):
        x += 1; i = x
        while i <= self.n:
            j = y + 1
            while j <= self.m:
                self.t[i][j] += v
                j += j & -j
            i += i & -i
    def query(self, x, y):
        x += 1; y += 1; s = 0; i = x
        while i > 0:
            j = y
            while j > 0:
                s += self.t[i][j]
                j -= j & -j
            i -= i & -i
        return s
